from __future__ import annotations

from fastapi import APIRouter
from fastapi.responses import HTMLResponse


HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OD-rclone</title><style>:root{color-scheme:dark;--bg:#0d1117;--card:#161b22;--line:#30363d;--text:#e6edf3;--muted:#8b949e;--accent:#58a6ff}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px system-ui,Segoe UI,sans-serif}main{max-width:1200px;margin:32px auto;padding:0 20px}input,button{background:#0d1117;border:1px solid var(--line);color:var(--text);border-radius:6px;padding:9px}button{cursor:pointer}.bar{display:grid;grid-template-columns:1fr 120px 120px;gap:8px}.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:16px;margin-top:16px}table{width:100%;border-collapse:collapse}th,td{text-align:left;border-bottom:1px solid var(--line);padding:9px;vertical-align:top}.muted{color:var(--muted)}.pill{padding:2px 6px;border:1px solid var(--line);border-radius:99px}</style></head><body><main><h1>OD-rclone</h1><p class="muted">Unified open-directory search, persistent virtual files, sparse cache, WebDAV, downloads, and Servarr bridge.</p><div class="card"><div class="bar"><input id="q" placeholder="Search filename/title, e.g. Example S01E01"><input id="ext" placeholder="mkv,mp4"><button onclick="search()">Search</button></div></div><div class="card"><h2>Search results</h2><div id="results" class="muted">No search yet.</div></div><div class="card"><h2>Virtual files</h2><div id="files"></div></div><div class="card"><h2>Downloads</h2><div id="downloads"></div></div><script>function fmt(n){if(n==null)return'?';let u=['B','KiB','MiB','GiB','TiB'],i=0;while(n>=1024&&i<u.length-1){n/=1024;i++}return n.toFixed(i?2:0)+' '+u[i]}async function search(){let q=document.querySelector('#q').value,ext=document.querySelector('#ext').value.split(',').map(x=>x.trim()).filter(Boolean);let r=await fetch('/api/search',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({query:q,extensions:ext,limit:100})});let d=await r.json();results.innerHTML='<table><tr><th>Provider</th><th>Filename</th><th>Size</th><th>Score</th><th></th></tr>'+d.results.map(x=>`<tr><td><span class=pill>${x.provider}</span></td><td>${x.filename}</td><td>${fmt(x.size)}</td><td>${x.score.toFixed(1)}</td><td><button onclick='virtualize(${JSON.stringify(JSON.stringify(x))})'>Virtualize</button></td></tr>`).join('')+'</table>'}async function virtualize(raw){let candidate=JSON.parse(raw);await fetch('/api/virtualize',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({candidate})});loadFiles()}async function loadFiles(){let d=await(await fetch('/api/files')).json();files.innerHTML='<table><tr><th>Path</th><th>Size</th><th>Cached</th><th>Sources</th><th></th></tr>'+d.map(x=>`<tr><td>${x.virtual_path}</td><td>${fmt(x.size)}</td><td>${fmt(x.cached_bytes)}</td><td>${x.sources.map(s=>s.provider+'@'+s.host).join('<br>')}</td><td><button onclick="downloadFile(${x.id})">Download</button> <a href="/api/stream${x.virtual_path}">stream</a></td></tr>`).join('')+'</table>'}async function downloadFile(id){await fetch('/api/downloads',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({virtual_file_id:id})});loadDownloads()}async function loadDownloads(){let d=await(await fetch('/api/downloads')).json();downloads.innerHTML='<table><tr><th>File</th><th>Status</th><th>Progress</th><th>Speed</th></tr>'+d.map(x=>`<tr><td>${x.filename}</td><td>${x.status}</td><td>${fmt(x.bytes_done)} / ${fmt(x.bytes_total)}</td><td>${fmt(x.speed_bps)}/s</td></tr>`).join('')+'</table>'}loadFiles();loadDownloads();setInterval(loadDownloads,3000)</script></main></body></html>'''


def create_webui_router():
    router = APIRouter()

    @router.get("/", response_class=HTMLResponse)
    async def root():
        return HTML

    return router
